package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="talent_scores", indexes={@Index(name="idx_talent_player", columnList="player_id"),@Index(name="idx_talent_generated", columnList="generated_at")})
public class TalentScore { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="player_id") @JsonIgnore private Player player; private Double score=0.0; private Double confidence=0.0; private String riskLevel; private LocalDateTime generatedAt=LocalDateTime.now(); public Double getScore(){return score;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public Player getPlayer(){return player;} public void setPlayer(Player player){this.player=player;} public void setScore(Double score){this.score=score;} public Double getConfidence(){return confidence;} public void setConfidence(Double confidence){this.confidence=confidence;} public String getRiskLevel(){return riskLevel;} public void setRiskLevel(String riskLevel){this.riskLevel=riskLevel;} public LocalDateTime getGeneratedAt(){return generatedAt;} public void setGeneratedAt(LocalDateTime generatedAt){this.generatedAt=generatedAt;} }
